e = 'Tab') begin transaction;                  declare @Params varchar(2000) = (select @StoreGrouping as StoreGrouping, @StoreGroup as StoreGroup, @SDate as SDate, @EDate as EDate for json path)		          --Create Stores Included Temp Table               select *         into #StoresIncluded         from dev_aloha.dbo.get_StoresIncluded (@StoreGrouping, @StoreGroup, @EDate)  		delete from toast.dbo.hstorder         where dateofbusiness between @SDate and @EDate         and storenum in (select storeid from #StoresIncluded)          delete from toast.dbo.hstServiceCharges         where dateofbusiness between @SDate and @EDate         and storenum in (select storeid from #StoresIncluded)          delete from toast.dbo.hstAppliedDiscounts         where dateofbusiness between @SDate and @EDate         and storenum in (select storeid from #StoresIncluded)          delete from toast.dbo.hstCheck         where dateofbusiness between @SDate and @EDate                 and storenum in (select storeid from #StoresIncluded)          delete from toast.dbo.hstPayment         where dateofbusiness between @SDate and @EDate          and storenum in (select storeid from #StoresIncluded)          delete from toast.dbo.hstItem         where dateofbusiness between @SDate and @EDate          and storenum in (select storeid from #StoresIncluded)          delete from dev_aloha.dbo.tbl_SalesDataByDayPart         where DateOfBusiness between @SDate and @EDate          and restaurantid in (select storeid from #StoresIncluded)          delete from dev_aloha.dbo.CheckData         where DateOfBusiness between @SDate and @EDate          and fkstoreid in (select storeid from #StoresIncluded)          delete from dev_aloha.dbo.CheckInfo         where DateOfBusiness between @SDate and @EDate          and storenumber in (select storeid from #StoresIncluded)          delete from dev_aloha.dbo.MenuMix         where DateOfBusiness between @SDate and @EDate          and fkstoreid in (select storeid from #StoresIncluded)                  -- If the table build has no error, then commit the transaction 		if (@RunType = 'Tab') commit transaction;                          -- Log the successful completion         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName 			,@Params = @Params;                  END TRY     BEGIN CATCH         -- If there are errors and a transaction was started, roll it back         IF @@TRANCOUNT > 0         ROLLBACK TRANSACTION;                  -- Record the error details         set @ErrorNumber  = ERROR_NUMBER();         set @ErrorLine  = ERROR_LINE();         set @ErrorMessage  = ERROR_MESSAGE();                  -- Log the error         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName             ,@ErrorNumber = @ErrorNumber             ,@ErrorMessage = @ErrorMessage             ,@ErrorLine = @ErrorLine 			,@Params = @Params;         THROW;     END CATCH END